button-led.source:
// Hold the button (D2 to GND) to light the LED on D13.
void setup() { pinMode(2, INPUT_PULLUP); pinMode(13, OUTPUT); }
void loop() { digitalWrite(13, digitalRead(2) == LOW ? HIGH : LOW); }

millis-blink.source:
// Non-blocking blink driven by millis() — needs Timer0 overflow interrupts working.
unsigned long last = 0;
bool on = false;
void setup() { pinMode(LED_BUILTIN, OUTPUT); }
void loop() {
  if (millis() - last >= 250) {
    last += 250;
    on = !on;
    digitalWrite(LED_BUILTIN, on);
  }
}

